<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#f7f7f5"><title><?=e(system_agent_name())?> | Appointment Lifecycle</title><link rel="stylesheet" href="<?=e(url('/chat.css?v=82'))?>"><link rel="stylesheet" href="<?=e(url('/appointment-lifecycle.css?v=agent-appointment-lifecycle-v700-20260911'))?>"></head>
<body class="lifecycle-page"><div class="chat-app"><?php $workspaceSidebarUser=$user;$workspaceSidebarActive='appointment_lifecycle';require __DIR__.'/member-sidebar.php';?>
<main class="lifecycle-main"><header class="lifecycle-header"><div><span>Phase 7</span><h1>Appointment Lifecycle</h1><p>Lifecycle, intake, reminders, Agent prep and post-meeting follow-up on one canonical booking.</p></div><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="run_automation"><input type="hidden" name="booking_id" value="<?=$selectedId?>"><button type="submit">Run due automation</button></form></header>
<?php if($saved!==''):?><div class="notice success"><?=e($saved)?></div><?php endif;?><?php if($pageError!==''):?><div class="notice error"><?=e($pageError)?></div><?php endif;?>
<section class="lifecycle-stats"><div><strong><?=$upcomingCount?></strong><span>Upcoming</span></div><div><strong><?=$completedCount?></strong><span>Completed</span></div><div><strong><?=$noShowCount?></strong><span>No-show</span></div><div><strong><?=count($bookings)?></strong><span>Total</span></div></section>
<div class="lifecycle-layout"><aside class="lifecycle-list"><h2>Appointments</h2><?php if(!$bookings):?><p>No appointments yet.</p><?php endif;?><?php foreach($bookings as $b):?><a class="<?= (int)$b['id']===$selectedId?'active':''?>" href="<?=e(url('/appointment-lifecycle.php?booking='.(int)$b['id']))?>"><strong><?=e((string)$b['guest_name'])?></strong><span><?=e((string)$b['event_title'])?></span><small><?=e(appointment_lifecycle_label_v700((string)$b['start_at_utc'],(string)$b['organizer_timezone']))?> · <?=e(agent_appointment_lifecycle_status_v700($b))?></small></a><?php endforeach;?></aside>
<section class="lifecycle-detail"><?php if(!$selected):?><article class="card"><h2>Select an appointment</h2><p>Choose a booking to manage its lifecycle.</p></article><?php else:?>
<article class="card" id="appointment"><div class="card-head"><div><span>Canonical booking #<?=(int)$selected['id']?></span><h2><?=e((string)$selected['event_title'])?> with <?=e((string)$selected['guest_name'])?></h2><p><?=e(appointment_lifecycle_label_v700((string)$selected['start_at_utc'],(string)$selected['organizer_timezone']))?></p></div><b><?=e(agent_appointment_lifecycle_status_v700($selected))?></b></div><div class="actions"><?php if(in_array((string)$selected['status'],['pending','confirmed'],true)):?><?php foreach(['completed'=>'Mark completed','no_show'=>'Mark no-show','cancelled'=>'Cancel'] as $to=>$label):?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="transition"><input type="hidden" name="booking_id" value="<?=(int)$selected['id']?>"><input type="hidden" name="to_status" value="<?=e($to)?>"><button class="<?=$to==='cancelled'?'danger':''?>" type="submit"><?=e($label)?></button></form><?php endforeach;?><?php endif;?></div></article>
<article class="card"><div class="card-head"><div><span>Attendee context</span><h2>Intake answers</h2></div><small><?=count($intake)?> answers</small></div><?php if(!$intake):?><p class="muted">No event-specific intake was captured.</p><?php else:?><dl><?php foreach($intake as $a):?><div><dt><?=e((string)$a['question_label'])?></dt><dd><?=e((string)($a['answer_text']??'—'))?></dd></div><?php endforeach;?></dl><?php endif;?></article>
<article class="card" id="brief"><div class="card-head"><div><span>Assigned Agent</span><h2>Meeting preparation</h2><p>Appointment + intake + prior messages + scoped CRM + relevant Knowledge.</p></div><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="prepare_brief"><input type="hidden" name="booking_id" value="<?=(int)$selected['id']?>"><button type="submit"><?=$brief?'Refresh brief':'Prepare brief'?></button></form></div><?php if($brief):?><pre><?=e((string)$brief['brief_text'])?></pre><?php else:?><p class="muted">The Agent prep job is queued automatically and can be generated now.</p><?php endif;?></article>
<article class="card" id="automation"><div class="card-head"><div><span>Automation</span><h2>Reminder delivery</h2></div><small><?=count($deliveries)?> jobs</small></div><div class="jobs"><?php foreach($deliveries as $d):?><div><strong><?=e(str_replace('_',' ',(string)$d['automation_key']))?></strong><span><?=e((string)$d['channel'])?> · <?=e((string)$d['recipient_key'])?></span><time><?=e((string)$d['due_at'])?> UTC</time><em><?=e((string)$d['status'])?></em></div><?php endforeach;?><?php if(!$deliveries):?><p class="muted">No automation jobs yet.</p><?php endif;?></div></article>
<article class="card" id="followup"><div class="card-head"><div><span>After the meeting</span><h2>Notes, tasks + follow-up</h2><p>Drafting is internal. Sending is a separately approved external action and is audited.</p></div><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="agent_followup"><input type="hidden" name="booking_id" value="<?=(int)$selected['id']?>"><button type="submit">Agent draft + task</button></form></div><form method="post" class="form-grid"><?=csrf_field()?><input type="hidden" name="action" value="save_followup"><input type="hidden" name="booking_id" value="<?=(int)$selected['id']?>"><label class="wide">Meeting notes<textarea name="notes" rows="3"></textarea></label><label>Follow-up task<input name="task_title" maxlength="190"></label><label>Due<input type="datetime-local" name="task_due_at"></label><label class="wide">Email subject<input name="draft_subject" maxlength="190" value="<?=e($defaultSubject)?>"></label><label class="wide">Email draft<textarea name="draft_body" rows="6"><?=e($defaultBody)?></textarea></label><button type="submit">Save post-meeting workflow</button></form><?php foreach($followups as $f):?><div class="followup" id="followup-<?=(int)$f['id']?>"><strong><?=e((string)($f['task_title']?:$f['draft_subject']?:'Follow-up'))?></strong><span><?=e((string)$f['message_status'])?> · <?=e((string)$f['created_at'])?> UTC</span><?php if((string)$f['message_status']==='draft'&&trim((string)($f['draft_body']??''))!==''):?><details><summary>Review draft</summary><pre><?=e((string)$f['draft_body'])?></pre><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="send_followup"><input type="hidden" name="booking_id" value="<?=(int)$selected['id']?>"><input type="hidden" name="followup_id" value="<?=(int)$f['id']?>"><label class="approve"><input type="checkbox" name="confirm_send" value="1" required> I approve sending this external email to <?=e((string)$selected['guest_email'])?>.</label><button type="submit">Send approved follow-up</button></form></details><?php endif;?></div><?php endforeach;?></article>
<article class="card"><div class="card-head"><div><span>Audit</span><h2>Lifecycle history</h2></div></div><div class="timeline"><?php foreach($lifecycle as $ev):?><div><strong><?=e(str_replace('_',' ',(string)$ev['event_type']))?></strong><span><?=e((string)$ev['from_status'])?> → <?=e((string)$ev['to_status'])?></span><small><?=e((string)$ev['created_at'])?> UTC · <?=e((string)$ev['actor_type'])?></small></div><?php endforeach;?><?php if(!$lifecycle):?><p class="muted">No Phase 7 lifecycle events yet.</p><?php endif;?></div></article>
<?php endif;?></section></div>
<section class="configuration" id="configuration"><div class="section-head"><span>Appointment-type automation</span><h2>Intake + timing</h2></div><?php if($eventTypes):?><nav><?php foreach($eventTypes as $evt):?><a class="<?= (int)$evt['id']===$configEventId?'active':''?>" href="<?=e(url('/appointment-lifecycle.php'.($selectedId?'?booking='.$selectedId.'&':'?').'event='.(int)$evt['id'].'#configuration'))?>"><?=e((string)$evt['title'])?></a><?php endforeach;?></nav><?php endif;?><?php if($configEvent):?><div class="config-grid"><article class="card"><h3>Automation timing</h3><form method="post" class="form-grid"><?=csrf_field()?><input type="hidden" name="action" value="save_automation_settings"><input type="hidden" name="booking_id" value="<?=$selectedId?>"><input type="hidden" name="event_type_id" value="<?=(int)$configEvent['id']?>"><label class="wide approve"><input type="checkbox" name="confirmation_enabled" value="1" <?=!empty($configEvent['confirmation_enabled'])?'checked':''?>> Booking confirmation</label><label class="wide approve"><input type="checkbox" name="reminder_24h_enabled" value="1" <?=!empty($configEvent['reminder_24h_enabled'])?'checked':''?>> 24-hour reminder</label><label>Soon reminder<input type="number" name="reminder_soon_minutes" min="5" max="240" value="<?=(int)$configEvent['reminder_soon_minutes']?>"></label><label>Agent prep<input type="number" name="agent_prep_minutes" min="15" max="1440" value="<?=(int)$configEvent['agent_prep_minutes']?>"></label><button type="submit">Save automation</button></form></article><article class="card" id="intake"><h3>Intake questions</h3><form method="post" class="form-grid"><?=csrf_field()?><input type="hidden" name="action" value="save_question"><input type="hidden" name="booking_id" value="<?=$selectedId?>"><input type="hidden" name="event_type_id" value="<?=(int)$configEvent['id']?>"><label class="wide">Question<input name="label" maxlength="500" required></label><label>Type<select name="question_type"><option value="short_text">Short text</option><option value="long_text">Long text</option><option value="select">Select</option><option value="checkbox">Checkbox</option></select></label><label>Order<input type="number" name="sort_order" value="<?=count($questions)*10?>"></label><label class="wide">Options<textarea name="options_text" rows="2"></textarea></label><label class="wide approve"><input type="checkbox" name="is_required" value="1"> Required before booking</label><button type="submit">Add intake question</button></form><?php foreach($questions as $q):?><div class="question"><span><strong><?=e((string)$q['label'])?></strong><small><?=e((string)$q['question_type'])?><?=!empty($q['is_required'])?' · required':''?></small></span><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="toggle_question"><input type="hidden" name="booking_id" value="<?=$selectedId?>"><input type="hidden" name="question_id" value="<?=(int)$q['id']?>"><button type="submit"><?=!empty($q['is_active'])?'Disable':'Enable'?></button></form></div><?php endforeach;?></article></div><?php endif;?></section>
</main></div></body></html>
